BEGIN;

CREATE TABLE IF NOT EXISTS products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, description text, currency text NOT NULL, cost_base numeric(10,2) NOT NULL, utility_fixed numeric(10,2) NOT NULL, utility_factor numeric(10,2) NOT NULL);
CREATE TABLE IF NOT EXISTS plantillas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nombre text NOT NULL, requerimiento text);
CREATE TABLE IF NOT EXISTS plantilla_items (plantilla_id uuid REFERENCES plantillas(id) ON DELETE CASCADE, sequence integer NOT NULL, product_id uuid REFERENCES products(id), qty numeric(10,2) NOT NULL DEFAULT 1);




COMMIT;
